from typing import List


class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        if len(targetIndices) >= len(source) - 1:
            return len(targetIndices) - m
        targets = set(targetIndices)
        neg = -10 ** 9
        dp = [0] + [neg] * m
        for i, c in enumerate(source):
            add = 1 if i in targets else 0
            for j in range(min(i + 1, m), 0, -1):
                if c == pattern[j - 1]:
                    dp[j] = max(dp[j] + add, dp[j - 1])
                else:
                    dp[j] += add
            dp[0] += add
        return dp[m]
